/**
 * THEO SLIDE LỚP JPD123 — Bài 4 và Bài 5 (Slot 1–10) + BT từ vựng/ngữ pháp + Ôn giữa kỳ.
 *
 * Mỗi buổi Slot = một lesson `slot-NN-…`: tóm tắt buổi, từng slide quan trọng (đúng thứ tự cô chiếu) có giải thích
 * bằng chữ, ngữ pháp đủ + ví dụ romaji + lỗi hay mắc + cách nhớ, bài luyện có đáp án, "cô hay hỏi gì".
 * Viết lời riêng theo nội dung slide (không chép nguyên văn); câu ví dụ chỉ dùng từ đã học đến Bài 5.
 * Đề BT/ôn giữa kỳ của cô là bản scan KHÔNG có đáp án ⇒ phần đáp án là TỰ GIẢI (ghi rõ trong bài).
 * Đối chiếu với bai4.ts/bai5.ts: scratchpad jp123/audit-b45.md.
 */
